std::vector<double> px;
px.reserve(1'000'000);   // preallocate: no reallocation during the session
px.push_back(42.17);     // amortised O(1)
double first = px[0];    // O(1) random access
px.erase(px.begin());    // O(n): shifts every element left
// px.data() hands you the raw contiguous buffer for SIMD/cache-friendly loops.

class Node:
    __slots__ = ("val", "next")
    def __init__(self, val, nxt=None):
        self.val = val
        self.next = nxt

class LinkedList:
    def __init__(self):
        self.head = None
        self.size = 0

    def prepend(self, val):              # O(1)
        self.head = Node(val, self.head)
        self.size += 1

    def append(self, val):               # O(n) without a tail pointer
        if self.head is None:
            self.head = Node(val)
        else:
            node = self.head
            while node.next:
                node = node.next
            node.next = Node(val)
        self.size += 1

    def delete(self, val):               # O(n) to find, O(1) to unlink
        prev, node = None, self.head
        while node and node.val != val:
            prev, node = node, node.next
        if node is None:
            return False
        if prev is None:
            self.head = node.next
        else:
            prev.next = node.next
        self.size -= 1
        return True
